    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Kelola Pengguna | KantongKu</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7f5;font-family: 'Inter', sans-serif;color:#26352d}.top{background:#18794e;color:white;padding:18px 7%;display:flex;justify-content:space-between;align-items:center}.top a{color:white}.wrap{max-width:1100px;margin:35px auto;padding:0 20px}.card{background:white;padding:24px;border-radius:14px;overflow-x:auto}.btn{padding:9px 13px;border:0;border-radius:7px;background:#18794e;color:white;text-decoration:none;cursor:pointer}.danger{background:#b42318}table{width:100%;border-collapse:collapse;min-width:650px}th,td{text-align:left;padding:13px;border-bottom:1px solid #edf0ed}.alert{padding:12px;background:#e4f5e9;color:#17663f;border-radius:8px;margin-bottom:15px}.actions{display:flex;gap:8px}.muted{color:#68756d}</style></head><body><header class="top"><strong>KantongKu · Admin</strong><nav><a href="{{ route('admin.dashboard') }}">Dashboard</a>　<a href="{{ route('logout') }}" onclick="event.preventDefault();document.getElementById('logout-form').submit()">Logout</a><form id="logout-form" method="POST" action="{{ route('logout') }}" hidden>@csrf</form></nav></header><main class="wrap"><p><a href="{{ route('admin.dashboard') }}">← Kembali ke dashboard</a></p><h1>Kelola Pengguna</h1><p class="muted">Daftar akun yang terdaftar di KantongKu.</p>@if(session('success'))<div class="alert">{{ session('success') }}</div>@endif<div class="card"><table><thead><tr><th>Nama</th><th>Email</th><th>Role</th><th>Terdaftar</th><th>Aksi</th></tr></thead><tbody>@forelse($users as $user)<tr><td>{{ $user->name }}</td><td>{{ $user->email }}</td><td>{{ ucfirst($user->role) }}</td><td>{{ $user->created_at?->format('d/m/Y') }}</td><td>@if($user->id !== auth()->id())<form method="POST" action="{{ route('admin.u